import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.EUByU7Iq.js";const u=JSON.parse('{"title":"第十章 公司财务、会计","description":"","frontmatter":{"title":"第十章 公司财务、会计","date":"2023-12-29T00:00:00.000Z","categories":["法律","公司法"],"tags":["法律","公司法"],"law_version":"2023修订（2023-12-29 公布，2024-07-01 施行）","v1_source":"blogs/CL/第十章：公司财务、会计.md"},"headers":[],"relativePath":"blogs/CL/dishizhang：gongsicaiwuhuiji.md","filePath":"blogs/CL/第十章：公司财务、会计.md"}'),i={name:"blogs/CL/dishizhang：gongsicaiwuhuiji.md"};function h(l,a,n,s,d,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="第十章-公司财务、会计" tabindex="-1">第十章 公司财务、会计 <a class="header-anchor" href="#第十章-公司财务、会计" aria-label="Permalink to &quot;第十章 公司财务、会计&quot;">​</a></h1><h3 id="第二百零七条" tabindex="-1">第二百零七条 <a class="header-anchor" href="#第二百零七条" aria-label="Permalink to &quot;第二百零七条&quot;">​</a></h3><p>七条公司应当依照法律、行政法规和国务院财政部门的规定建立本公司的财务、会计制度。</p><h3 id="第二百零八条" tabindex="-1">第二百零八条 <a class="header-anchor" href="#第二百零八条" aria-label="Permalink to &quot;第二百零八条&quot;">​</a></h3><p>八条公司应当在每一会计年度终了时编制财务会计报告，并依法经会计师事务所审计。 财务会计报告应当依照法律、行政法规和国务院财政部门的规定制作。</p><h3 id="第二百零九条" tabindex="-1">第二百零九条 <a class="header-anchor" href="#第二百零九条" aria-label="Permalink to &quot;第二百零九条&quot;">​</a></h3><p>九条有限责任公司应当按照公司章程规定的期限将财务会计报告送交各股东。 股份有限公司的财务会计报告应当在召开股东会年会的二十日前置备于本公司，供股东查阅；公开发行股份的股份有限公司应当公告其财务会计报告。</p><h3 id="第二百一十条" tabindex="-1">第二百一十条 <a class="header-anchor" href="#第二百一十条" aria-label="Permalink to &quot;第二百一十条&quot;">​</a></h3><p>十条公司分配当年税后利润时，应当提取利润的百分之十列入公司法定公积金。公司法定公积金累计额为公司注册资本的百分之五十以上的，可以不再提取。 公司的法定公积金不足以弥补以前年度亏损的，在依照前款规定提取法定公积金之前，应当先用当年利润弥补亏损。 公司从税后利润中提取法定公积金后，经股东会决议，还可以从税后利润中提取任意公积金。 公司弥补亏损和提取公积金后所余税后利润，有限责任公司按照股东实缴的出资比例分配利润，全体股东约定不按照出资比例分配利润的除外；股份有限公司按照股东所持有的股份比例分配利润，公司章程另有规定的除外。 公司持有的本公司股份不得分配利润。</p><h3 id="第二百一十一条" tabindex="-1">第二百一十一条 <a class="header-anchor" href="#第二百一十一条" aria-label="Permalink to &quot;第二百一十一条&quot;">​</a></h3><p>一条公司违反本法规定向股东分配利润的，股东应当将违反规定分配的利润退还公司；给公司造成损失的，股东及负有责任的董事、监事、高级管理人员应当承担赔偿责任。</p><h3 id="第二百一十二条" tabindex="-1">第二百一十二条 <a class="header-anchor" href="#第二百一十二条" aria-label="Permalink to &quot;第二百一十二条&quot;">​</a></h3><p>二条股东会作出分配利润的决议的，董事会应当在股东会决议作出之日起六个月内进行分配。</p><h3 id="第二百一十三条" tabindex="-1">第二百一十三条 <a class="header-anchor" href="#第二百一十三条" aria-label="Permalink to &quot;第二百一十三条&quot;">​</a></h3><p>三条公司以超过股票票面金额的发行价格发行股份所得的溢价款、发行无面额股所得股款未计入注册资本的金额以及国务院财政部门规定列入资本公积金的其他项目，应当列为公司资本公积金。</p><h3 id="第二百一十四条" tabindex="-1">第二百一十四条 <a class="header-anchor" href="#第二百一十四条" aria-label="Permalink to &quot;第二百一十四条&quot;">​</a></h3><p>四条公司的公积金用于弥补公司的亏损、扩大公司生产经营或者转为增加公司注册资本。 公积金弥补公司亏损，应当先使用任意公积金和法定公积金；仍不能弥补的，可以按照规定使用资本公积金。 法定公积金转为增加注册资本时，所留存的该项公积金不得少于转增前公司注册资本的百分之二十五。</p><h3 id="第二百一十五条" tabindex="-1">第二百一十五条 <a class="header-anchor" href="#第二百一十五条" aria-label="Permalink to &quot;第二百一十五条&quot;">​</a></h3><p>五条公司聘用、解聘承办公司审计业务的会计师事务所，按照公司章程的规定，由股东会、董事会或者监事会决定。 公司股东会、董事会或者监事会就解聘会计师事务所进行表决时，应当允许会计师事务所陈述意见。</p><h3 id="第二百一十六条" tabindex="-1">第二百一十六条 <a class="header-anchor" href="#第二百一十六条" aria-label="Permalink to &quot;第二百一十六条&quot;">​</a></h3><p>六条公司应当向聘用的会计师事务所提供真实、完整的会计凭证、会计账簿、财务会计报告及其他会计资料，不得拒绝、隐匿、谎报。</p><h3 id="第二百一十七条" tabindex="-1">第二百一十七条 <a class="header-anchor" href="#第二百一十七条" aria-label="Permalink to &quot;第二百一十七条&quot;">​</a></h3><p>七条公司除法定的会计账簿外，不得另立会计账簿。 对公司资金，不得以任何个人名义开立账户存储。</p><hr><p class="law-foot">本篇依据《中华人民共和国公司法》2023 年 12 月 29 日第十四届全国人大常委会第七次会议第二次修订文本，自 2024 年 7 月 1 日起施行；本站同步于 2026-11-07。</p>',25)])])}const _=e(i,[["render",h]]);export{u as __pageData,_ as default};
